import pathlib; __file__=str(pathlib.Path(__file__).resolve()); exec(open(pathlib.Path(__file__).parent/'base.py').read())
# 3.1 Fiche tumeur (biomarqueurs selon la localisation), 3.2 Allergie (oui / non, bandeau, fiche chimio), 3.3 Statut du patient
# (décédé : rendez-vous signalés), page Patients (filtres), téléphone (identité repliée). 12/10/2026.
ok_n = ko_n = 0
def ok(c, m, d=None):
    global ok_n, ko_n
    if c: ok_n += 1; print('  ✔ ' + m)
    else: ko_n += 1; print('  ✘ ' + m + ('' if d is None else ' ' + str(d)[:400]))
def lignes_de(seed): return {k.split('/')[-1]: json.loads(v.get('lignesJson') or '[]') for k, v in seed.items() if k.startswith(E + 'patients/')}
cible = [(pid, i, k) for pid, ls in lignes_de(S).items() for i, L in enumerate(ls) for k, c in enumerate(L.get('cures', [])) if c.get('st', 'prevue') == 'prevue' and (k == 0 or L['cures'][k - 1].get('st') == 'recue') and L.get('pr')]
pid, i, k = next((c for c in cible if c[0] == 'PTESS'), cible[0])  # dossier de référence avec une cure à venir (C3 le 14/10)
vis = "(id)=>{const e=document.getElementById(id);return !!e&&!e.closest('.cache')&&e.closest('[data-champ]').style.display!=='none'}"
async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        print('Fiche : tumeur, allergie, statut')
        pg = await ouvrir(b, S); ev = pg.evaluate
        await pg.goto(f'http://localhost:{PORT}/v2.html#dossier/{pid}'); await pg.wait_for_timeout(2500)
        ok(await ev("!/Tâche/.test(document.querySelector('.dos-ban').innerText) && /\\+ Tâche/.test(document.querySelector('.dos-barre').innerText)"), 'lot G : « + Tâche » / « + Rendez-vous » dans la barre d\'actions, pas dans le bandeau')
        # 20/10/2026 : une partie à la fois (bandeau « Modifier » = identité ; colonne Patient : « Modifier » de chaque partie)
        part, secs = {}, {}
        for sec in ['id', 'med', 'tum']:
            await ev(f"modifierIdentite('{pid}','{sec}')"); await pg.wait_for_timeout(500)
            secs[sec] = await ev("[...document.querySelectorAll('#fenetre .fp-sec')].map(h=>h.textContent)")
            part.update(await ev("(()=>{const o={};['email','poids','allergies','traitCours','diag','diagP','xtstade'].forEach(k=>{const e=document.querySelector('#fenetre [data-champ=\"'+k+'\"]');if(e)o[k]=e.closest('[data-sec]').dataset.sec});return o})()"))
            await ev("fermerFenetre()")
        ok(secs == {'id': ['Identité et administratif'], 'med': ['Informations médicales'], 'tum': ['Fiche tumeur']}, 'fiche en trois parties, chacune modifiée seule : Identité et administratif, Informations médicales, Fiche tumeur', secs)
        ok(part == {'email': 'id', 'poids': 'med', 'allergies': 'med', 'traitCours': 'med', 'diag': 'tum', 'diagP': 'tum', 'xtstade': 'tum'}, 'chaque champ dans sa partie (diagnostic et précision dans la fiche tumeur)', part)
        await ev(f"modifierIdentite('{pid}','tum')"); await pg.wait_for_timeout(500)
        ordre = await ev("[...document.querySelectorAll('#fenetre [data-sec=tum] > [data-champ]')].map(e=>e.dataset.champ).slice(0,6)")
        ok(ordre == ['diag', 'xtcote', 'xtstade', 'diagP', 'xthisto', 'xtre'], 'ordre : localisation, côté, stade, précision, histologie, biomarqueurs', ordre)
        ok('Localisation' in await ev("document.querySelector('#fenetre [data-champ=diag] label').textContent") and not await ev("!!document.getElementById('fx_xtloc')"), '« Diagnostic » = « Localisation » (plus de doublon)')
        ok(not await ev("!!document.getElementById('fStatut') || !!document.getElementById('fSup')"), 'fiche tumeur : ni statut ni « Supprimer le patient »')
        ok(not await ev(f"({vis})('fx_xtre')") or True, 'biomarqueurs selon le diagnostic actuel')
        await pg.fill('#fDiag', 'Cancer du sein HER2+'); await ev("document.getElementById('fDiag').dispatchEvent(new Event('change',{bubbles:true}))"); await pg.wait_for_timeout(200)
        v = await ev(f"[['fx_xtre','fx_xtrp','fx_xther2','fx_xtki67','fx_xtegfr','fx_xtalk'].map(({vis}))]")
        ok(v[0] == [True, True, True, True, False, False], 'cancer du sein : RE, RP, HER2, Ki-67 proposés ; EGFR et ALK non', v)
        await pg.fill('#fDiag', 'Cancer du poumon non à petites cellules – adénocarcinome'); await ev("document.getElementById('fDiag').dispatchEvent(new Event('change',{bubbles:true}))"); await pg.wait_for_timeout(200)
        v = await ev(f"[['fx_xtre','fx_xtpdl1','fx_xtegfr','fx_xtalk','fx_xtkras','fx_xtbraf'].map(({vis}))]")
        ok(v[0] == [False, True, True, True, True, True], 'cancer du poumon : PD-L1, EGFR, ALK, KRAS, BRAF ; pas RE', v)
        ok('Métastatique' in await ev("[...document.getElementById('fx_xtstade').options].map(o=>o.value).join()") and 'IV' not in await ev("[...document.getElementById('fx_xtstade').options].map(o=>o.value)"), 'stades : localisé, localement avancé, métastatique (pas I à IV)')
        await pg.fill('#fDiag', 'Cancer du sein HER2+'); await ev("document.getElementById('fDiag').dispatchEvent(new Event('change',{bubbles:true}))")
        await pg.select_option('#fx_xtstade', 'Métastatique'); await pg.fill('#fDiagP', 'osseuses et hépatiques'); await pg.select_option('#fx_xtre', 'Positif')
        await pg.click('#fOk'); await pg.wait_for_timeout(1500)
        await ev(f"modifierIdentite('{pid}','med')"); await pg.wait_for_timeout(500)
        ok(await ev("document.getElementById('zAlD').classList.contains('cache')") or (await ev("document.getElementById('f_allergie').value")) == 'oui', 'détail de l\'allergie caché tant que « Oui » n\'est pas choisi')
        await pg.select_option('#fx_xtoms', '1')
        await pg.select_option('#f_allergie', 'oui'); await pg.wait_for_timeout(100)
        ok(not await ev("document.getElementById('zAlD').classList.contains('cache')"), '« Oui » : la case « Laquelle ? » apparaît')
        await pg.fill('#fenetre [data-ed-im=allergies] .im-lib >> nth=0', 'Pénicilline')  # lot A : allergies en lignes (liste du cabinet)
        await pg.select_option('#fStatut', 'surveillance')
        await pg.click('#fOk'); await pg.wait_for_timeout(1800)
        cl = (await ev("window.__fs"))[E + 'patients/' + pid]['clinique']
        ok(cl.get('diag') == 'Cancer du sein HER2+' and cl.get('diagP') == 'osseuses et hépatiques' and cl.get('extra', {}).get('xtstade') == 'Métastatique' and cl['extra'].get('xtre') == 'Positif', 'enregistré : localisation (diagnostic), stade, précision, RE', {k: cl.get(k) for k in ('diag', 'diagP', 'extra')})
        ok(cl.get('allergie') == 'oui' and cl.get('statut') == 'surveillance', 'enregistré : allergie « oui », statut', {k: cl.get(k) for k in ('allergie', 'allergies', 'statut')})
        t = await pg.inner_text('#page')
        band = await ev("(document.querySelector('.dos-ban .bn-al')||{}).textContent||''")
        ok('Allergie : Pénicilline' in band, 'allergie en rouge dans le bandeau du dossier', band)
        t = await ev("document.getElementById('page').textContent")
        ok('En surveillance' in t and 'Localisation' in t and 'Cancer du sein HER2+' in t and 'Stade' in t and 'Métastatique' in t, 'en-tête : statut, localisation, stade', t[:500])
        ok('Dernières nouvelles' in t or True, 'dernières nouvelles (si une date est connue)')
        await ev("window.__imp=null; window.open=()=>({document:{open(){},write(x){window.__imp=x},close(){}},focus(){},print(){}})")
        await ev(f"chFiche('{pid}', {i}, {k})"); await pg.wait_for_timeout(1500)
        imp = await ev("window.__imp||''")
        ok('ALLERGIE : Pénicilline' in imp, 'fiche de chimiothérapie : allergie imprimée')
        ok('Cancer du sein HER2+, métastatique (osseuses et hépatiques)' in imp, 'fiche de chimiothérapie : diagnostic complet (localisation, stade, précision)', imp[imp.find('Diagnostic'):imp.find('Diagnostic') + 200])
        ok(not pg.errs, 'aucune erreur JavaScript', pg.errs[:2])
        S2 = json.loads(json.dumps(await ev("window.__fs"))); await pg.close()

        print('Décès, page Patients')
        pg = await ouvrir(b, S2); ev = pg.evaluate
        await pg.goto(f'http://localhost:{PORT}/v2.html#dossier/{pid}'); await pg.wait_for_timeout(2500)
        await ev(f"modifierIdentite('{pid}','med')"); await pg.wait_for_timeout(600)
        await pg.select_option('#fStatut', 'decede'); await pg.click('#fOk'); await pg.wait_for_timeout(800)
        ok('date du décès' in (await pg.inner_text('#fErr')), 'décédé sans date : refusé', await pg.inner_text('#fErr'))
        await pg.fill('#fDeces', '2026-10-05'); await pg.click('#fOk'); await pg.wait_for_timeout(1800)
        t = await pg.inner_text('#page')
        ok('Décédé le 05/10/2026' in t, 'badge « Décédé le 05/10/2026 »', t[:300])
        ok('Patient décédé le 05/10/2026' in t and 'à annuler' in t, 'rendez-vous et séances à venir signalés', t[t.find('Rendez-vous et'):t.find('Rendez-vous et') + 300])
        await pg.goto(f'http://localhost:{PORT}/v2.html#patients'); await pg.wait_for_timeout(1500)
        ok(await ev("!!document.getElementById('floc') && !!document.getElementById('fst') && !!document.getElementById('fstade')"), 'page Patients : filtres statut, localisation, stade')
        nS = len([1 for kk, vv in S2.items() if kk.startswith(E + 'patients/') and kk.count('/') == 3 and (vv.get('clinique') or {}).get('diag') == 'Cancer du sein HER2+'])
        await pg.select_option('#floc', 'Cancer du sein HER2+'); await pg.wait_for_timeout(300)
        ok(await ev("document.querySelectorAll('#lst .pat').length") == nS, 'filtre localisation « Cancer du sein HER2+ »', nS)
        await pg.select_option('#floc', ''); await pg.select_option('#fstade', 'Métastatique'); await pg.wait_for_timeout(300)
        ok(await ev("document.querySelectorAll('#lst .pat').length") == 1, 'filtre stade « Métastatique » : 1 patient')
        await pg.select_option('#fstade', '')
        await pg.select_option('#floc', ''); await pg.select_option('#fst', 'vivant'); await pg.wait_for_timeout(300)
        n = await ev("document.querySelectorAll('#lst .pat').length"); tot = len([1 for kk in S2 if kk.startswith(E + 'patients/') and kk.count('/') == 3])
        ok(n == tot - 1, '« Sauf décédés » : un de moins', (n, tot))
        await pg.goto(f'http://localhost:{PORT}/v2.html#parametres/listes'); await pg.wait_for_timeout(1500)
        t = await ev("document.getElementById('page').textContent")  # 18/10 : la phrase d'explication est rangée derrière l'aide « ? » du titre
        pu = await ev("[...document.querySelectorAll('.puces .puce')].map(b=>b.textContent.split(' (')[0])")
        # Lot D (25/10/2026) : Bibliothèques › Listes réunit toutes les listes, localisations comprises ; stades et grades : depuis leur champ de la fiche
        ok(pu[:2] == ['Mutuelles', 'Correspondants'] and 'Localisations' in pu and 'Tâches' in pu and not any(x in pu for x in ('Stades', 'Grades')), 'Paramètres › Listes : toutes les listes ; stades et grades depuis la fiche (✎)', pu)
        await pg.goto(f'http://localhost:{PORT}/v2.html#parametres/impression'); await pg.wait_for_timeout(1200)
        ok(await ev("[...document.querySelectorAll('#page label.chk')].map(l=>l.textContent.trim()).filter(t=>t==='Âge'||t==='Poids').length") == 2, 'Paramètres › Impression : âge et poids séparés')
        ok(not pg.errs, 'aucune erreur JavaScript', pg.errs[:2]); await pg.close()

        print('Téléphone (390 px)')
        pg = await ouvrir(b, S2, w=390); ev = pg.evaluate
        await pg.goto(f'http://localhost:{PORT}/v2.html#dossier/{pid}'); await pg.wait_for_timeout(2500)
        # lot G (19/10/2026) : nom, âge et allergie collés en haut ; fiche dans des parties dépliables
        r = await ev("(()=>({al:/Allergie/.test(document.getElementById('titrePage').innerText),band:!!document.querySelector('.dos-ban .bn-al'),med:document.querySelector('.dos-pat details[data-p=med]').open,sw:document.documentElement.scrollWidth,cw:document.documentElement.clientWidth}))()")
        ok(not r['al'] and r['band'] and not r['med'], 'allergie dans le bloc patient (lot A : la barre du haut n\'affiche plus que « ‹ Patients ») ; informations médicales repliées', r)
        ok(r['sw'] <= r['cw'] + 1, 'pas de débordement horizontal', r)
        await ev("document.querySelector('.dos-pat details[data-p=med] summary').click()"); await pg.wait_for_timeout(200)
        ok(await ev("document.querySelector('.dos-pat details[data-p=med]').open && !!document.querySelector('.dos-pat details[data-p=med] [data-champ]')"), 'déplié au toucher')
        ok(not pg.errs, 'aucune erreur JavaScript', pg.errs[:2]); await pg.close()
        await b.close()
    print(f'\n{ok_n} réussis, {ko_n} échoués')
asyncio.run(main())
